import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

import {
  LEGACY_RULE_ALIASES,
  SSC_RULE_CHAPTERS,
} from "../src/lib/ssc-rules/canon-v4-source";

const outputPath = resolve(process.cwd(), "src/lib/ssc-rules/canon-v4.generated.ts");

function renderGeneratedCanon() {
  return [
    "// Generated by scripts/generate-ssc-rules-static-canon.ts. Do not edit by hand.",
    'import type { SscRuleChapter } from "@/lib/ssc-rules/types";',
    "",
    `export const CANONICAL_RULE_CHAPTERS: SscRuleChapter[] = ${JSON.stringify(SSC_RULE_CHAPTERS, null, 2)};`,
    "",
    `export const CANONICAL_LEGACY_RULE_ALIASES: Record<string, string> = ${JSON.stringify(LEGACY_RULE_ALIASES, null, 2)};`,
    "",
  ].join("\n");
}

const generated = renderGeneratedCanon();
const checkOnly = process.argv.includes("--check");

if (checkOnly) {
  let existing = "";
  try {
    existing = readFileSync(outputPath, "utf8");
  } catch {
    console.error("Static SSC V4 canon is missing. Run: bun run scripts/generate-ssc-rules-static-canon.ts");
    process.exit(1);
  }

  if (existing !== generated) {
    console.error(
      "Static SSC V4 canon is stale. Regenerate it with: bun run scripts/generate-ssc-rules-static-canon.ts",
    );
    process.exit(1);
  }

  console.log("Static SSC V4 canon matches the authoritative source compiler.");
  process.exit(0);
}

writeFileSync(outputPath, generated);
console.log(`Wrote ${outputPath}`);
